const vertexShader='varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}';
const header='uniform sampler2D hbScreenSource,hbScreenDepth,hbScreenHistory,hbSurfaceNormal,hbSurfaceAlbedo,hbObjectMotion,hbDepthHierarchy,hbGeometryScene,hbPathEnvironmentScene;uniform mat4 hbInverseVP,hbCurrentVP,hbPreviousVP;uniform vec4 hbTemporal,hbMotion,hbReflection,hbIndirect,hbCoordinates,hbJitter,hbEye,hbForward,hbCamera,hbHierarchy,hbGeometry,hbGeometryInfo,hbGeometryLimits,hbAmbientAO,hbPath,hbPathQuality,hbPathEnvironment,hbPathLens,hbPathMap,hbPathOptions,hbPathDenoise,hbTransport;uniform sampler2D hbSurfaceAmbient,hbDenoiseGuide;uniform vec2 hbScreenSize;';
const linear='float hbLinearDepth(float d){return hbCamera.z>.5?mix(hbCamera.x,hbCamera.y,d):hbCamera.x*hbCamera.y/max(.000001,hbCamera.y-d*(hbCamera.y-hbCamera.x));}';
export class ScreenEffectsPass extends Pass{
 constructor(){super();this.state=new ScreenFrameState();this.images=[0,1].map(()=>new WebGLRenderTarget(1,1,{type:HalfFloatType,depthBuffer:false}));this.index=0;this.pathState=new ProgressivePathState();const uniforms=Object.fromEntries(['Source','Depth','History','SurfaceNormal','SurfaceAlbedo','ObjectMotion','DepthHierarchy','GeometryScene','SurfaceAmbient','DenoiseGuide'].map(k=>[(k.startsWith('Surface')||k==='ObjectMotion'||k==='DepthHierarchy'||k==='GeometryScene'||k==='DenoiseGuide')?'hb'+k:'hbScreen'+k,{value:null}]));uniforms.hbPathEnvironmentScene={value:null};for(const key of ['Temporal','Motion','Reflection','Indirect','Coordinates','Jitter','Eye','Forward','Camera','Hierarchy','Geometry','GeometryInfo','GeometryLimits','AmbientAO','Path','PathQuality','PathEnvironment','PathLens','PathMap','PathOptions','PathDenoise','Transport'])uniforms['hb'+key]={value:new Vector4()};for(const key of ['InverseVP','CurrentVP','PreviousVP'])uniforms['hb'+key]={value:new Matrix4()};uniforms.hbScreenSize={value:new Vector2()};this.material=new ShaderMaterial({defines:{HB_WEBGL_RAY_DATA:1},uniforms,vertexShader,fragmentShader:'varying vec2 vUv;'+header+linear+screenEffectsGLSL.replace(pathDenoiseGLSL,'')+'void main(){gl_FragColor=hbScreenResolve(vUv);}',depthTest:false,depthWrite:false,toneMapped:false});this.copy=new ShaderMaterial({uniforms:{hbResolved:{value:null},hbRaw:{value:null},hbPathAlpha:{value:0}},vertexShader,fragmentShader:'uniform sampler2D hbResolved,hbRaw;uniform float hbPathAlpha;varying vec2 vUv;void main(){gl_FragColor=vec4(texture2D(hbResolved,vUv).rgb,mix(texture2D(hbRaw,vUv).a,1.0,hbPathAlpha));}',depthTest:false,depthWrite:false,toneMapped:false});this.baseFragment=this.material.fragmentShader;this.quad=new FullScreenQuad(this.material);}
 configurePrograms(info={},pathOnly=false,environment=false,lights=true){const operationKey=JSON.stringify([info.programs,info.fields,pathOnly,!!info.medium,!!info.advanced,!!info.roughDielectric,environment,lights]);if(operationKey!==this.operationKey){this.disposeDenoiser();this.material.dispose();this.operationKey=operationKey;this.material.defines=Object.fromEntries((info.operations||[]).map(op=>['HB_RAY_OP_'+op,1]));this.material.defines.HB_WEBGL_RAY_DATA=1;if(info.advanced)this.material.defines.HB_PATH_ADVANCED=1;if(info.roughDielectric)this.material.defines.HB_PATH_ROUGH_DIELECTRIC=1;if(!pathOnly)this.material.defines.HB_RAY_NO_PATH=1;if(!lights)this.material.defines.HB_RAY_NO_ANALYTIC_LIGHTS=1;this.material.defines.HB_RAY_REGISTERS=info.registers||1;for(const field of info.fields||[])this.material.defines['HB_RAY_FIELD_'+field]=1;if(!info.instructions)this.material.defines.HB_RAY_CONSTANT_FIELDS=1;const fragment=info.programs?this.baseFragment:this.baseFragment.replace(geometryGIGLSL,'vec3 hbGeometryIndirect(vec3 p,vec3 n){return vec3(0,0,0);}').replace(pathTracingGLSL,'vec4 hbPathResolve(vec2 uv){return texture2D(hbScreenSource,uv);}');this.material.fragmentShader=fragment.replace(pathEnvironmentGLSL,environment?pathEnvironmentGLSL:'vec4 hbEnvironmentLod(vec3 d,float spread){return vec4(hbPathEnvironment.rgb,0.0);}vec4 hbEnvironment(vec3 d){return hbEnvironmentLod(d,0.0);}vec3 hbEnvironmentDirect(vec3 p,vec3 n,vec3 v,float id,float seed,float width,float spread,float ratio){return vec3(0,0,0);}').replace('/*HB_RAY_PROGRAMS*/',rayProgramGLSL(info.programs||[])).replace('/*HB_RAY_PROGRAM_CALL*/','result=hbRayExecute(program.w,program.x,id,point,view,result,width);');if(info.medium)this.material.defines.HB_PATH_MEDIA=1;if(pathOnly)this.material.defines.HB_PATH_ONLY=1;this.material.needsUpdate=true;}}
 prepare(frame,camera,scene,p){const u=this.material.uniforms;for(const [key,value]of Object.entries(frame.packed)){const name='hb'+key[0].toUpperCase()+key.slice(1);if(u[name])u[name].value.fromArray(value);}if(frame.packed.path[0]===0)this.pathState.reset();configurePathLens(frame.packed,camera,p);if(frame.packed.geometry[0]>0||frame.packed.path[0]>0){this.geometry??=new GeometryGIWorld();const p=bindTransport(frame.packed,this.geometry,scene);this.configurePrograms(p.rayInfo,frame.packed.path[0]>0,p.pathMap[1]>0,p.lightCount>0);if(frame.packed.path[0]>0)this.pathState.prepare(frame.packed,this.geometry,frame.reset);for(const key of ['path','pathQuality','pathLens','pathMap','pathOptions','transport'])u['hb'+key[0].toUpperCase()+key.slice(1)].value.fromArray(frame.packed[key]);this.frame=frame;u.hbGeometryScene.value=this.geometry.texture;u.hbPathEnvironmentScene.value=this.geometry.environmentTexture;u.hbGeometryInfo.value.set(p.width,p.height,p.nodeCount,p.triangleOffset);u.hbGeometryLimits.value.z=p.lightsOffset;u.hbGeometryLimits.value.w=p.lightCount;}else if(this.geometry){this.geometry.dispose();this.geometry=null;u.hbGeometryScene.value=null;u.hbPathEnvironmentScene.value=null;this.pathState.reset();}if(frame.packed.geometry[0]===0&&frame.packed.path[0]===0)this.configurePrograms();u.hbScreenSize.value.fromArray(frame.packed.size);u.hbCamera.value.set(camera.near,camera.far,camera.isOrthographicCamera?1:0,Math.abs(camera.projectionMatrix.elements[5])*.5);}
 disposeDenoiser(){if(!this.denoiser)return;for(const image of this.denoiser.images)image.dispose();for(const material of this.denoiser.materials)material.dispose();this.denoiser=null;}
 denoise(renderer,raw){const u=this.material.uniforms;if(u.hbPath.value.x===0||u.hbPathDenoise.value.x===0){this.disposeDenoiser();return raw;}
  if(!this.denoiser){const images=[0,1,2].map(()=>new WebGLRenderTarget(raw.width,raw.height,{type:HalfFloatType,depthBuffer:false})),materials=['hbPathGuideResolve','hbPathDenoiseResolve'].map(fn=>{const material=this.material.clone();material.uniforms=u;material.defines={...material.defines,HB_RAY_NO_PATH:1,HB_RAY_NO_GI:1,HB_RAY_NO_ANALYTIC_LIGHTS:1,HB_RAY_NO_ENV:1};material.fragmentShader=pathGuideFragment(this.material.fragmentShader).replace('void main(){',pathDenoiseGLSL+'void main(){').replace('gl_FragColor=hbScreenResolve(vUv);','gl_FragColor='+fn+'(vUv);');return material;});this.denoiser={images,materials};}
  const {images,materials}=this.denoiser;for(const image of images)image.setSize(raw.width,raw.height);renderer.setRenderTarget(images[0]);this.quad.material=materials[0];this.quad.render(renderer);u.hbDenoiseGuide.value=images[0].texture;let image=raw;
  for(let step=0;step<u.hbPathDenoise.value.y;step++){const next=images[1+step%2];u.hbScreenSource.value=image.texture;u.hbPathOptions.value.w=2**step;renderer.setRenderTarget(next);this.quad.material=materials[1];this.quad.render(renderer);image=next;}return image;
 }
 setSize(w,h){for(const image of this.images)image.setSize(w,h);this.state.reset();this.pathState.reset();}
 render(renderer,write,read){read=this.raw||read;const u=this.material.uniforms;u.hbObjectMotion.value=this.motion?.target.texture||null;u.hbScreenSource.value=read.texture;u.hbScreenDepth.value=read.depthTexture;u.hbSurfaceNormal.value=read.textures[1]||null;u.hbSurfaceAlbedo.value=read.textures[2]||null;u.hbSurfaceAmbient.value=read.textures[3]||null;u.hbScreenHistory.value=this.images[this.index].texture;if(u.hbHierarchy.value.w>.5){this.hiz??=new HierarchicalDepthPass();u.hbDepthHierarchy.value=this.hiz.render(renderer,read.depthTexture,read.width,read.height);const l=this.hiz.layout;u.hbHierarchy.value.set(l.width,l.height,l.levels.length,1);}else if(this.hiz){this.hiz.dispose();this.hiz=null;u.hbDepthHierarchy.value=null;}const result=this.images[1-this.index];renderer.setRenderTarget(result);this.quad.material=this.material;this.quad.render(renderer);this.copy.uniforms.hbPathAlpha.value=u.hbPath.value.x;this.copy.uniforms.hbResolved.value=this.denoise(renderer,result).texture;this.copy.uniforms.hbRaw.value=read.texture;renderer.setRenderTarget(this.renderToScreen?null:write);this.quad.material=this.copy;this.quad.render(renderer);this.index=1-this.index;if(this.frame?.packed.path[0]>0)this.pathState.commit(this.frame.packed);}
 dispose(){this.disposeDenoiser();this.geometry?.dispose();this.hiz?.dispose();for(const image of this.images)image.dispose();this.material.dispose();this.copy.dispose();this.quad.dispose();}
}
